return new {scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path,player=UnityEngine.Object.FindFirstObjectByType<ThuyKieu.Player.PlayerMovement>().name,validationRunning=ThuyKieu.Player.Editor.ThuyKieuPlayModeCheck.IsRunning,clips=UnityEditor.AssetDatabase.FindAssets("t:Model",new[]{"Assets/_Game/Animations/ThuyKieu"}).Select(UnityEditor.AssetDatabase.GUIDToAssetPath).SelectMany(p=>UnityEditor.AssetDatabase.LoadAllAssetsAtPath(p).OfType<UnityEngine.AnimationClip>().Where(c=>!c.name.StartsWith("__preview__")).Select(c=>new{p,c.name,c.isHumanMotion,c.isLooping,c.length})).ToArray()};
